-- ============================================================================
-- GRIMORIO TAROT - ESQUEMA Y SEMILLAS CANÓNICAS PARA TURSO (LIBSQL)
-- Generado automáticamente para despliegue en la nube
-- ============================================================================

PRAGMA foreign_keys = ON;

-- ----------------------------------------------------------------------------
-- 1. TABLAS DEL SISTEMA
-- ----------------------------------------------------------------------------
-- Tabla: appointments
CREATE TABLE IF NOT EXISTS "appointments" (
          id TEXT PRIMARY KEY,
          user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          consultant_id TEXT NOT NULL REFERENCES consultants(id) ON DELETE CASCADE,
          title TEXT NOT NULL,
          scheduled_at TEXT NOT NULL,
          duration_minutes INTEGER,
          modality TEXT NOT NULL CHECK (modality IN ('in_person', 'video', 'audio', 'written')),
          status TEXT NOT NULL CHECK (status IN ('scheduled', 'completed', 'cancelled')),
          intention TEXT NOT NULL DEFAULT '',
          prep_notes TEXT NOT NULL DEFAULT '',
          linked_reading_id TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );

-- Tabla: card_entries
CREATE TABLE IF NOT EXISTS card_entries (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  card_id TEXT NOT NULL REFERENCES cards_catalog(id),
  deck_id TEXT REFERENCES decks(id) ON DELETE SET NULL,
  custom_image_url TEXT,
  personal_meaning TEXT NOT NULL DEFAULT '',
  reversed_meaning TEXT NOT NULL DEFAULT '',
  symbols_associations TEXT NOT NULL DEFAULT '',
  keywords_json TEXT NOT NULL DEFAULT '[]',
  reflections TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL,
  UNIQUE(user_id, card_id, deck_id)
);

-- Tabla: card_interpretation_logs
CREATE TABLE IF NOT EXISTS card_interpretation_logs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  card_id TEXT NOT NULL REFERENCES cards_catalog(id),
  deck_id TEXT REFERENCES decks(id) ON DELETE SET NULL,
  reading_id TEXT REFERENCES readings(id) ON DELETE SET NULL,
  note_title TEXT NOT NULL,
  content TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- Tabla: cards_catalog
CREATE TABLE IF NOT EXISTS "cards_catalog" (
          id TEXT PRIMARY KEY,
          slug TEXT NOT NULL UNIQUE,
          arcana TEXT NOT NULL,
          suit TEXT,
          rank_number INTEGER NOT NULL,
          roman_numeral TEXT,
          canonical_name TEXT NOT NULL,
          name_en TEXT NOT NULL DEFAULT '',
          deck_tradition TEXT NOT NULL DEFAULT 'rws',
          search_keywords_json TEXT NOT NULL DEFAULT '[]',
          traditional_upright TEXT NOT NULL,
          traditional_reversed TEXT NOT NULL,
          traditional_keywords_json TEXT NOT NULL,
          archetype_note TEXT NOT NULL
        );

-- Tabla: consultants
CREATE TABLE IF NOT EXISTS consultants (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  full_name TEXT NOT NULL,
  alias TEXT,
  email TEXT,
  phone TEXT,
  preferred_channel TEXT,
  context_notes TEXT NOT NULL DEFAULT '',
  personal_notes TEXT NOT NULL DEFAULT '',
  avatar_hue INTEGER NOT NULL DEFAULT 168,
  archived_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, needs_setup INTEGER NOT NULL DEFAULT 0);

-- Tabla: deck_events
CREATE TABLE IF NOT EXISTS deck_events (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reading_id TEXT NOT NULL REFERENCES readings(id) ON DELETE CASCADE,
  card_id TEXT REFERENCES cards_catalog(id),
  occurred_phase TEXT NOT NULL CHECK (occurred_phase IN ('shuffling', 'cutting', 'dealing', 'base_of_deck', 'closing', 'other')),
  phenomenon_type TEXT NOT NULL CHECK (phenomenon_type IN ('jumped', 'fell_to_floor', 'base_card', 'cut_reveal', 'partially_hidden', 'spontaneous_turn', 'out_of_order', 'other')),
  custom_phenomenon_label TEXT,
  linked_position_index INTEGER,
  observation_description TEXT NOT NULL,
  personal_interpretation TEXT NOT NULL DEFAULT '',
  occurred_at TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- Tabla: decks
CREATE TABLE IF NOT EXISTS "decks" (
          id TEXT PRIMARY KEY,
          user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          name TEXT NOT NULL,
          tradition TEXT NOT NULL,
          author TEXT,
          card_count INTEGER NOT NULL DEFAULT 78,
          description TEXT NOT NULL DEFAULT '',
          is_default INTEGER NOT NULL DEFAULT 0,
          needs_setup INTEGER NOT NULL DEFAULT 0,
          created_at TEXT NOT NULL
        );

-- Tabla: entity_tags
CREATE TABLE IF NOT EXISTS entity_tags (
  tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  entity_type TEXT NOT NULL CHECK (entity_type IN ('consultant', 'reading', 'deck_event', 'card_entry')),
  entity_id TEXT NOT NULL,
  PRIMARY KEY (tag_id, entity_type, entity_id)
);

-- Tabla: reading_cards
CREATE TABLE IF NOT EXISTS reading_cards (
  id TEXT PRIMARY KEY,
  reading_id TEXT NOT NULL REFERENCES readings(id) ON DELETE CASCADE,
  position_index INTEGER NOT NULL,
  position_title TEXT NOT NULL,
  position_prompt TEXT NOT NULL DEFAULT '',
  card_id TEXT NOT NULL REFERENCES cards_catalog(id),
  orientation TEXT NOT NULL CHECK (orientation IN ('upright', 'reversed')),
  observation_notes TEXT NOT NULL DEFAULT '',
  contextual_interpretation TEXT NOT NULL DEFAULT '',
  personal_takeaway TEXT NOT NULL DEFAULT '',
  synced_to_grimorio INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

-- Tabla: readings
CREATE TABLE IF NOT EXISTS readings (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  consultant_id TEXT REFERENCES consultants(id) ON DELETE SET NULL,
  appointment_id TEXT REFERENCES appointments(id) ON DELETE SET NULL,
  deck_id TEXT REFERENCES decks(id) ON DELETE SET NULL,
  spread_template_id TEXT REFERENCES spread_templates(id) ON DELETE SET NULL,
  spread_name TEXT NOT NULL,
  title TEXT NOT NULL,
  question_intention TEXT NOT NULL DEFAULT '',
  session_context TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL CHECK (status IN ('draft', 'completed')),
  performed_at TEXT NOT NULL,
  general_observations TEXT NOT NULL DEFAULT '',
  session_synthesis TEXT NOT NULL DEFAULT '',
  closing_reflections TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, deck_ids_json TEXT NOT NULL DEFAULT '[]', custom_positions_json TEXT NOT NULL DEFAULT '[]');

-- Tabla: sessions
CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- Tabla: spread_templates
CREATE TABLE IF NOT EXISTS spread_templates (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  positions_json TEXT NOT NULL,
  is_builtin INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

-- Tabla: tags
CREATE TABLE IF NOT EXISTS tags (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  normalized_name TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('general', 'phenomenon', 'theme', 'consultant')),
  created_at TEXT NOT NULL,
  UNIQUE(user_id, normalized_name)
);

-- Tabla: users
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  workspace_name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  is_demo INTEGER NOT NULL DEFAULT 0,
  preferences_json TEXT NOT NULL DEFAULT '{"defaultDeckId":null,"defaultSpreadId":null,"compactTables":false,"autosaveReadings":true}',
  created_at TEXT NOT NULL
);

-- ----------------------------------------------------------------------------
-- 2. ÍNDICES DE RENDIMIENTO
-- ----------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_appointments_consultant ON appointments(consultant_id);
CREATE INDEX IF NOT EXISTS idx_appointments_user_date ON appointments(user_id, scheduled_at);
CREATE INDEX IF NOT EXISTS idx_card_entries_user_card ON card_entries(user_id, card_id);
CREATE INDEX IF NOT EXISTS idx_card_logs_user_card ON card_interpretation_logs(user_id, card_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_consultants_user ON consultants(user_id);
CREATE INDEX IF NOT EXISTS idx_deck_events_card ON deck_events(card_id);
CREATE INDEX IF NOT EXISTS idx_deck_events_reading ON deck_events(reading_id);
CREATE INDEX IF NOT EXISTS idx_deck_events_user ON deck_events(user_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_decks_user ON decks(user_id);
CREATE INDEX IF NOT EXISTS idx_entity_tags_lookup ON entity_tags(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_reading_cards_card ON reading_cards(card_id);
CREATE INDEX IF NOT EXISTS idx_reading_cards_reading ON reading_cards(reading_id);
CREATE INDEX IF NOT EXISTS idx_readings_consultant ON readings(consultant_id);
CREATE INDEX IF NOT EXISTS idx_readings_user_date ON readings(user_id, performed_at DESC);
CREATE INDEX IF NOT EXISTS idx_sessions_token ON sessions(token_hash);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_spread_templates_user ON spread_templates(user_id);

-- ----------------------------------------------------------------------------
-- 3. CATÁLOGO CANÓNICO DE CARTAS (318 CARTAS MULTI-TRADICIÓN)
-- ----------------------------------------------------------------------------
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-01', 'lenormand-01-el-jinete', 'lenormand', NULL, 1, '1', '1. El Jinete (The Rider)', 'The Rider', 'lenormand', '["1. El Jinete (The Rider)","El Jinete","The Rider","1","Carta 1","9 de Corazones","Lenormand","Oráculo","noticias","visita","rapidez","mensajero","movimiento"]', 'Llegada inminente de noticias, visitas veloces, dinamismo y mensajes frescos en camino. [Correspondencia: 9 de Corazones].', 'Retraso en la comunicación, noticia superficial o movimiento precipitado.', '["noticias","visita","rapidez","mensajero","movimiento","9 de corazones"]', 'Carta #1 del Petit Lenormand (9 de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-02', 'lenormand-02-el-tr-bol', 'lenormand', NULL, 2, '2', '2. El Trébol (The Clover)', 'The Clover', 'lenormand', '["2. El Trébol (The Clover)","El Trébol","The Clover","2","Carta 2","6 de Diamantes","Lenormand","Oráculo","suerte","oportunidad","alivio","ligereza","fortuna"]', 'Golpe de fortuna breve y dulce, oportunidad imprevista, alivio y ligereza. [Correspondencia: 6 de Diamantes].', 'Suerte desaprovechada por desatención o liviandad efímera.', '["suerte","oportunidad","alivio","ligereza","fortuna","6 de diamantes"]', 'Carta #2 del Petit Lenormand (6 de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-03', 'lenormand-03-el-barco', 'lenormand', NULL, 3, '3', '3. El Barco (The Ship)', 'The Ship', 'lenormand', '["3. El Barco (The Ship)","El Barco","The Ship","3","Carta 3","10 de Picas","Lenormand","Oráculo","viaje","distancia","comercio","anhelo","transición"]', 'Travesías y viajes largos, anhelos de ultramar, comercio, transición hacia horizontes amplios. [Correspondencia: 10 de Picas].', 'Postergación de un viaje, desarraigo incómodo o nostalgia lejana.', '["viaje","distancia","comercio","anhelo","transición","10 de picas"]', 'Carta #3 del Petit Lenormand (10 de Picas).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-04', 'lenormand-04-la-casa', 'lenormand', NULL, 4, '4', '4. La Casa (The House)', 'The House', 'lenormand', '["4. La Casa (The House)","La Casa","The House","4","Carta 4","Rey de Corazones","Lenormand","Oráculo","hogar","familia","estabilidad","raíces","refugio"]', 'Hogar seguro, intimidad familiar, raíces estables, refugio y bienestar doméstico. [Correspondencia: Rey de Corazones].', 'Inseguridad en el entorno doméstico, reparaciones o tensiones familiares.', '["hogar","familia","estabilidad","raíces","refugio","rey de corazones"]', 'Carta #4 del Petit Lenormand (Rey de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-05', 'lenormand-05-el-rbol', 'lenormand', NULL, 5, '5', '5. El Árbol (The Tree)', 'The Tree', 'lenormand', '["5. El Árbol (The Tree)","El Árbol","The Tree","5","Carta 5","7 de Corazones","Lenormand","Oráculo","salud","vitalidad","crecimiento lento","raíces","longevidad"]', 'Vitalidad orgánica, salud duradera, paciencia con los ritmos biológicos y arraigo ancestral. [Correspondencia: 7 de Corazones].', 'Desgaste energético, necesidad de descanso o lentitud exasperante.', '["salud","vitalidad","crecimiento lento","raíces","longevidad","7 de corazones"]', 'Carta #5 del Petit Lenormand (7 de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-06', 'lenormand-06-las-nubes', 'lenormand', NULL, 6, '6', '6. Las Nubes (The Clouds)', 'The Clouds', 'lenormand', '["6. Las Nubes (The Clouds)","Las Nubes","The Clouds","6","Carta 6","Rey de Tréboles","Lenormand","Oráculo","confusión","duda","clima incierto","transitorio"]', 'Confusión pasajera, clima incierto, dudas que ocultan el panorama pero pasarán con el viento. [Correspondencia: Rey de Tréboles].', 'Niebla que se disipa paulatinamente o persistencia obstinada en la duda.', '["confusión","duda","clima incierto","transitorio","rey de tréboles"]', 'Carta #6 del Petit Lenormand (Rey de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-07', 'lenormand-07-la-serpiente', 'lenormand', NULL, 7, '7', '7. La Serpiente (The Snake)', 'The Snake', 'lenormand', '["7. La Serpiente (The Snake)","La Serpiente","The Snake","7","Carta 7","Reina de Tréboles","Lenormand","Oráculo","astucia","desvío","complejidad","hipocresía","cautela"]', 'Complejidad sinuosa, desvío estratégico necesario, astucia e instinto de autopreservación. [Correspondencia: Reina de Tréboles].', 'Traición hipócrita, celos sutiles o veneno en el trato cotidiano.', '["astucia","desvío","complejidad","hipocresía","cautela","reina de tréboles"]', 'Carta #7 del Petit Lenormand (Reina de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-08', 'lenormand-08-el-ata-d', 'lenormand', NULL, 8, '8', '8. El Ataúd (The Coffin)', 'The Coffin', 'lenormand', '["8. El Ataúd (The Coffin)","El Ataúd","The Coffin","8","Carta 8","9 de Diamantes","Lenormand","Oráculo","final","cierre","transformación","duelo","clausura"]', 'Clausura inevitable y definitiva, fin de un ciclo agotado, parada forzosa que abre otra etapa. [Correspondencia: 9 de Diamantes].', 'Resistencia al duelo, prolongación artificial de lo muerto o estancamiento mórbido.', '["final","cierre","transformación","duelo","clausura","9 de diamantes"]', 'Carta #8 del Petit Lenormand (9 de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-09', 'lenormand-09-el-ramillete', 'lenormand', NULL, 9, '9', '9. El Ramillete (The Bouquet)', 'The Bouquet', 'lenormand', '["9. El Ramillete (The Bouquet)","El Ramillete","The Bouquet","9","Carta 9","Reina de Picas","Lenormand","Oráculo","regalo","aprecio","gratitud","belleza","reconciliación"]', 'Regalo inesperado, gratitud, aprecio manifestado, belleza, alegría social y reconciliación. [Correspondencia: Reina de Picas].', 'Cortesía interesada, halago superficial o belleza efímera.', '["regalo","aprecio","gratitud","belleza","reconciliación","reina de picas"]', 'Carta #9 del Petit Lenormand (Reina de Picas).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-10', 'lenormand-10-la-guada-a', 'lenormand', NULL, 10, '10', '10. La Guadaña (The Scythe)', 'The Scythe', 'lenormand', '["10. La Guadaña (The Scythe)","La Guadaña","The Scythe","10","Carta 10","Sota de Diamantes","Lenormand","Oráculo","corte","peligro","cosecha","repentino","decisión tajante"]', 'Corte tajante y repentino, peligro súbito, decisión que siega la hierba sin anestesia. [Correspondencia: Sota de Diamantes].', 'Ruptura dolorosa imprevista, accidente o necesidad de podar con urgencia.', '["corte","peligro","cosecha","repentino","decisión tajante","sota de diamantes"]', 'Carta #10 del Petit Lenormand (Sota de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-11', 'lenormand-11-el-l-tigo-la-vara-', 'lenormand', NULL, 11, '11', '11. El Látigo (La Vara) (The Whip)', 'The Whip', 'lenormand', '["11. El Látigo (La Vara) (The Whip)","El Látigo (La Vara)","The Whip","11","Carta 11","Sota de Tréboles","Lenormand","Oráculo","disputa","tensión","debate","entrenamiento","conflicto"]', 'Conversación áspera, entrenamiento físico riguroso, discusiones repetitivas y purga de tensión. [Correspondencia: Sota de Tréboles].', 'Agresividad verbal, castigo inútil o bucle de reproches desgastantes.', '["disputa","tensión","debate","entrenamiento","conflicto","sota de tréboles"]', 'Carta #11 del Petit Lenormand (Sota de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-12', 'lenormand-12-los-p-jaros', 'lenormand', NULL, 12, '12', '12. Los Pájaros (The Birds)', 'The Birds', 'lenormand', '["12. Los Pájaros (The Birds)","Los Pájaros","The Birds","12","Carta 12","7 de Diamantes","Lenormand","Oráculo","conversación","llamada","rumor","nerviosismo","charlas"]', 'Charlas cotidianas, llamadas telefónicas, agitación nerviosa menor, chismes y cotilleo sin dolo. [Correspondencia: 7 de Diamantes].', 'Ansiedad por rumores, estrés por sobreestimulación comunicacional.', '["conversación","llamada","rumor","nerviosismo","charlas","7 de diamantes"]', 'Carta #12 del Petit Lenormand (7 de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-13', 'lenormand-13-la-ni-a-el-ni-o-', 'lenormand', NULL, 13, '13', '13. La Niña (El Niño) (The Child)', 'The Child', 'lenormand', '["13. La Niña (El Niño) (The Child)","La Niña (El Niño)","The Child","13","Carta 13","Sota de Picas","Lenormand","Oráculo","inocencia","comienzo","infancia","frescura","pequeñez"]', 'Inocencia, nuevo brote pequeño, frescura infantil, proyecto en pañales o presencia de un hijo. [Correspondencia: Sota de Picas].', 'Inmadurez irresponsable, ingenuidad imprudente o pequeñez mezquina.', '["inocencia","comienzo","infancia","frescura","pequeñez","sota de picas"]', 'Carta #13 del Petit Lenormand (Sota de Picas).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-14', 'lenormand-14-el-zorro', 'lenormand', NULL, 14, '14', '14. El Zorro (The Fox)', 'The Fox', 'lenormand', '["14. El Zorro (The Fox)","El Zorro","The Fox","14","Carta 14","9 de Tréboles","Lenormand","Oráculo","trabajo","astucia","estrategia","trampa","cautela laboral"]', 'Estrategia sagaz en el empleo diario, discreción laboral, supervivencia por la propia maña. [Correspondencia: 9 de Tréboles].', 'Engaño premeditado en el trabajo, trampa solapada o desconfianza paranoica.', '["trabajo","astucia","estrategia","trampa","cautela laboral","9 de tréboles"]', 'Carta #14 del Petit Lenormand (9 de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-15', 'lenormand-15-el-oso', 'lenormand', NULL, 15, '15', '15. El Oso (The Bear)', 'The Bear', 'lenormand', '["15. El Oso (The Bear)","El Oso","The Bear","15","Carta 15","10 de Tréboles","Lenormand","Oráculo","fuerza","protección","finanzas","autoridad","nutrición"]', 'Poderío protector, solvencia financiera firme, figura nutricia autorizada y fuerza protectora. [Correspondencia: 10 de Tréboles].', 'Abuso de autoridad, celos posesivos o peso aplastante de un superior.', '["fuerza","protección","finanzas","autoridad","nutrición","10 de tréboles"]', 'Carta #15 del Petit Lenormand (10 de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-16', 'lenormand-16-las-estrellas', 'lenormand', NULL, 16, '16', '16. Las Estrellas (The Stars)', 'The Stars', 'lenormand', '["16. Las Estrellas (The Stars)","Las Estrellas","The Stars","16","Carta 16","6 de Corazones","Lenormand","Oráculo","claridad","inspiración","guía","destino","esperanza"]', 'Claridad celestial de propósito, inspiración lúcida, proyectos bendecidos y esperanza confirmada. [Correspondencia: 6 de Corazones].', 'Idealismo desconectado de la tierra, dispersión de ilusiones o ceguera nocturna.', '["claridad","inspiración","guía","destino","esperanza","6 de corazones"]', 'Carta #16 del Petit Lenormand (6 de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-17', 'lenormand-17-la-cig-e-a', 'lenormand', NULL, 17, '17', '17. La Cigüeña (The Stork)', 'The Stork', 'lenormand', '["17. La Cigüeña (The Stork)","La Cigüeña","The Stork","17","Carta 17","Reina de Corazones","Lenormand","Oráculo","mudanza","cambio","renovación","nacimiento","traslado"]', 'Mudanza física, cambio de entorno muy positivo, renovación de ciclo vital, nacimiento o viaje. [Correspondencia: Reina de Corazones].', 'Inestabilidad crónica, resistencia a mudar de piel o traslado demorado.', '["mudanza","cambio","renovación","nacimiento","traslado","reina de corazones"]', 'Carta #17 del Petit Lenormand (Reina de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-18', 'lenormand-18-el-perro', 'lenormand', NULL, 18, '18', '18. El Perro (The Dog)', 'The Dog', 'lenormand', '["18. El Perro (The Dog)","El Perro","The Dog","18","Carta 18","10 de Corazones","Lenormand","Oráculo","lealtad","amistad","fidelidad","aliado","confianza"]', 'Fidelidad sincera, lealtad a toda prueba, aliado incondicional y amistad profunda. [Correspondencia: 10 de Corazones].', 'Dependencia servil, amigo que decepciona o necesidad excesiva de compañía.', '["lealtad","amistad","fidelidad","aliado","confianza","10 de corazones"]', 'Carta #18 del Petit Lenormand (10 de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-19', 'lenormand-19-la-torre', 'lenormand', NULL, 19, '19', '19. La Torre (The Tower)', 'The Tower', 'lenormand', '["19. La Torre (The Tower)","La Torre","The Tower","19","Carta 19","6 de Picas","Lenormand","Oráculo","institución","soledad","ley","perspectiva","estructura"]', 'Estructuras legales, instituciones oficiales, perspectiva elevada, soledad y retiro lúcido. [Correspondencia: 6 de Picas].', 'Aislamiento frío, laberinto burocrático o encierro arrogante.', '["institución","soledad","ley","perspectiva","estructura","6 de picas"]', 'Carta #19 del Petit Lenormand (6 de Picas).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-20', 'lenormand-20-el-jard-n', 'lenormand', NULL, 20, '20', '20. El Jardín (The Garden)', 'The Garden', 'lenormand', '["20. El Jardín (The Garden)","El Jardín","The Garden","20","Carta 20","8 de Picas","Lenormand","Oráculo","comunidad","público","reunión","redes","vida social"]', 'Vida pública y social, redes abiertas, auditorio, fiestas, reuniones comunitarias y visibilidad. [Correspondencia: 8 de Picas].', 'Exposición incómoda, superficialidad mundana o agobio por la mirada ajena.', '["comunidad","público","reunión","redes","vida social","8 de picas"]', 'Carta #20 del Petit Lenormand (8 de Picas).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-21', 'lenormand-21-la-monta-a', 'lenormand', NULL, 21, '21', '21. La Montaña (The Mountain)', 'The Mountain', 'lenormand', '["21. La Montaña (The Mountain)","La Montaña","The Mountain","21","Carta 21","8 de Tréboles","Lenormand","Oráculo","obstáculo","bloqueo","demora","frontera","firmeza"]', 'Gran obstáculo rígido, bloqueo que no cede, frontera que exige paciencia o búsqueda de otro camino. [Correspondencia: 8 de Tréboles].', 'Bloqueo que empieza a franquearse o aislamiento congelado.', '["obstáculo","bloqueo","demora","frontera","firmeza","8 de tréboles"]', 'Carta #21 del Petit Lenormand (8 de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-22', 'lenormand-22-los-caminos', 'lenormand', NULL, 22, '22', '22. Los Caminos (The Crossroad)', 'The Crossroad', 'lenormand', '["22. Los Caminos (The Crossroad)","Los Caminos","The Crossroad","22","Carta 22","Reina de Diamantes","Lenormand","Oráculo","opciones","encrucijada","elección","caminos","bifurcación"]', 'Bifurcación ineludible, libre albedrío, decisión entre dos opciones concretas en la mesa. [Correspondencia: Reina de Diamantes].', 'Indecisión crónica en la encrucijada o extravío de rumbo.', '["opciones","encrucijada","elección","caminos","bifurcación","reina de diamantes"]', 'Carta #22 del Petit Lenormand (Reina de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-23', 'lenormand-23-los-ratones', 'lenormand', NULL, 23, '23', '23. Los Ratones (The Mice)', 'The Mice', 'lenormand', '["23. Los Ratones (The Mice)","Los Ratones","The Mice","23","Carta 23","7 de Tréboles","Lenormand","Oráculo","desgaste","pérdida","estrés","merma","ansiedad"]', 'Desgaste silencioso y continuo, pequeñas pérdidas cotidianas, estrés que roe la energía. [Correspondencia: 7 de Tréboles].', 'Freno al drenaje energético o descuido que empeora la merma.', '["desgaste","pérdida","estrés","merma","ansiedad","7 de tréboles"]', 'Carta #23 del Petit Lenormand (7 de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-24', 'lenormand-24-el-coraz-n', 'lenormand', NULL, 24, '24', '24. El Corazón (The Heart)', 'The Heart', 'lenormand', '["24. El Corazón (The Heart)","El Corazón","The Heart","24","Carta 24","Sota de Corazones","Lenormand","Oráculo","amor","afecto","pasión","generosidad","corazón"]', 'Amor generoso, pasión correspondida, afecto sincero, alegría del pecho y perdón. [Correspondencia: Sota de Corazones].', 'Desamor doloroso, frialdad afectiva o posesividad sentimental.', '["amor","afecto","pasión","generosidad","corazón","sota de corazones"]', 'Carta #24 del Petit Lenormand (Sota de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-25', 'lenormand-25-el-anillo', 'lenormand', NULL, 25, '25', '25. El Anillo (The Ring)', 'The Ring', 'lenormand', '["25. El Anillo (The Ring)","El Anillo","The Ring","25","Carta 25","As de Tréboles","Lenormand","Oráculo","compromiso","alianza","contrato","matrimonio","pacto"]', 'Pacto formal, firma de contrato, compromiso duradero, matrimonio o ciclo que sella un acuerdo. [Correspondencia: As de Tréboles].', 'Ruptura de acuerdo, contrato leonino o promesa que se quiebra.', '["compromiso","alianza","contrato","matrimonio","pacto","as de tréboles"]', 'Carta #25 del Petit Lenormand (As de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-26', 'lenormand-26-el-libro', 'lenormand', NULL, 26, '26', '26. El Libro (The Book)', 'The Book', 'lenormand', '["26. El Libro (The Book)","El Libro","The Book","26","Carta 26","10 de Diamantes","Lenormand","Oráculo","estudio","secreto","conocimiento","documento","misterio"]', 'Conocimiento reservado, estudio minucioso, secreto aún no revelado, documento cerrado. [Correspondencia: 10 de Diamantes].', 'Secreto expuesto sin prudencia, ignorancia voluntaria o misterio desentrañado.', '["estudio","secreto","conocimiento","documento","misterio","10 de diamantes"]', 'Carta #26 del Petit Lenormand (10 de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-27', 'lenormand-27-la-carta', 'lenormand', NULL, 27, '27', '27. La Carta (The Letter)', 'The Letter', 'lenormand', '["27. La Carta (The Letter)","La Carta","The Letter","27","Carta 27","7 de Picas","Lenormand","Oráculo","documento","correo","mensaje","papeles","comunicado"]', 'Documento escrito, correspondencia formal, correo electrónico, contrato o papel certificado. [Correspondencia: 7 de Picas].', 'Mensaje extraviado, demora en recibir papeles o notificación temida.', '["documento","correo","mensaje","papeles","comunicado","7 de picas"]', 'Carta #27 del Petit Lenormand (7 de Picas).');
