INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-30', 'lenormand-30-los-lirios', 'lenormand', NULL, 30, '30', '30. Los Lirios (The Lily)', 'The Lily', 'lenormand', '["30. Los Lirios (The Lily)","Los Lirios","The Lily","30","Carta 30","Rey de Picas","Lenormand","Oráculo","paz","madurez","serenidad","virtud","sabiduría"]', 'Paz madura, serenidad ética, pureza de intenciones, sabiduría templada y goce tranquilo. [Correspondencia: Rey de Picas].', 'Escándalo que ensucia la reputación, frialdad senil o hipocresía moral.', '["paz","madurez","serenidad","virtud","sabiduría","rey de picas"]', 'Carta #30 del Petit Lenormand (Rey de Picas).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-31', 'lenormand-31-el-sol', 'lenormand', NULL, 31, '31', '31. El Sol (The Sun)', 'The Sun', 'lenormand', '["31. El Sol (The Sun)","El Sol","The Sun","31","Carta 31","As de Diamantes","Lenormand","Oráculo","éxito","vitalidad","claridad","alegría","calor"]', 'Gran éxito radiante, calor vital vigoroso, resolución lúcida, alegría expansiva y plenitud. [Correspondencia: As de Diamantes].', 'Disminución de vitalidad, orgullo desmedido o nubes pasajeras sobre el éxito.', '["éxito","vitalidad","claridad","alegría","calor","as de diamantes"]', 'Carta #31 del Petit Lenormand (As de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-32', 'lenormand-32-la-luna', 'lenormand', NULL, 32, '32', '32. La Luna (The Moon)', 'The Moon', 'lenormand', '["32. La Luna (The Moon)","La Luna","The Moon","32","Carta 32","8 de Corazones","Lenormand","Oráculo","reputación","intuición","emociones","fama","psiquis"]', 'Reconocimiento y reputación en el medio, intuición psíquica, sueños intensos y resonancia afectiva. [Correspondencia: 8 de Corazones].', 'Inestabilidad emocional, susceptibilidad nocturna o pérdida de prestigio.', '["reputación","intuición","emociones","fama","psiquis","8 de corazones"]', 'Carta #32 del Petit Lenormand (8 de Corazones).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-33', 'lenormand-33-la-llave', 'lenormand', NULL, 33, '33', '33. La Llave (The Key)', 'The Key', 'lenormand', '["33. La Llave (The Key)","La Llave","The Key","33","Carta 33","8 de Diamantes","Lenormand","Oráculo","solución","certeza","destino","llave","apertura"]', 'Certeza absoluta, solución maestra al alcance, éxito kármico que abre todas las puertas. [Correspondencia: 8 de Diamantes].', 'Puerta cerrada temporalmente por falta de madurez o solución descuidada.', '["solución","certeza","destino","llave","apertura","8 de diamantes"]', 'Carta #33 del Petit Lenormand (8 de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-34', 'lenormand-34-los-peces', 'lenormand', NULL, 34, '34', '34. Los Peces (The Fish)', 'The Fish', 'lenormand', '["34. Los Peces (The Fish)","Los Peces","The Fish","34","Carta 34","Rey de Diamantes","Lenormand","Oráculo","dinero","abundancia","negocios","fluidez","prosperidad"]', 'Abundancia económica en movimiento, negocios prósperos, fluidez material y libertad fecunda. [Correspondencia: Rey de Diamantes].', 'Gastos desmedidos, dispersión de capital o codicia que enturbia las aguas.', '["dinero","abundancia","negocios","fluidez","prosperidad","rey de diamantes"]', 'Carta #34 del Petit Lenormand (Rey de Diamantes).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-35', 'lenormand-35-el-ancla', 'lenormand', NULL, 35, '35', '35. El Ancla (The Anchor)', 'The Anchor', 'lenormand', '["35. El Ancla (The Anchor)","El Ancla","The Anchor","35","Carta 35","9 de Picas","Lenormand","Oráculo","seguridad","empleo","estabilidad","anclaje","firmeza"]', 'Estabilidad a largo plazo, empleo seguro, anclaje firme tras la tormenta y puerto de paz. [Correspondencia: 9 de Picas].', 'Inmovilidad asfixiante, terquedad rutinaria o peso que hunde el avance.', '["seguridad","empleo","estabilidad","anclaje","firmeza","9 de picas"]', 'Carta #35 del Petit Lenormand (9 de Picas).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lenormand-36', 'lenormand-36-la-cruz', 'lenormand', NULL, 36, '36', '36. La Cruz (The Cross)', 'The Cross', 'lenormand', '["36. La Cruz (The Cross)","La Cruz","The Cross","36","Carta 36","6 de Tréboles","Lenormand","Oráculo","destino","prueba","fe","carga kármica","consagración"]', 'Prueba de destino, carga necesaria con propósito evolutivo, fe probada y consagración. [Correspondencia: 6 de Tréboles].', 'Sufrimiento innecesario, victimismo culposo o alivio de una pesada carga.', '["destino","prueba","fe","carga kármica","consagración","6 de tréboles"]', 'Carta #36 del Petit Lenormand (6 de Tréboles).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-01', 'livingwheel-zodiac-01-aries', 'astrological', 'zodiac', 1, '♈', '♈ Aries (El Carnero)', 'Aries (The Ram)', 'living_wheel', '["♈ Aries (El Carnero)","Aries (El Carnero)","Aries (The Ram)","♈","zodiac","1","Living Wheel","Astrología","Astrológico","fuego cardinal","iniciativa","coraje","aries","primer impulso"]', 'Impulso primordial de inicio, coraje audaz, iniciativa directa y afirmación del ser.', 'Impulsividad agresiva, impaciencia destructiva o dispersión por arrancar sin sostén.', '["fuego cardinal","iniciativa","coraje","aries","primer impulso"]', 'La chispa que abre la rueda del zodíaco con fuerza motriz pura. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-02', 'livingwheel-zodiac-02-tauro', 'astrological', 'zodiac', 2, '♉', '♉ Tauro (El Toro)', 'Taurus (The Bull)', 'living_wheel', '["♉ Tauro (El Toro)","Tauro (El Toro)","Taurus (The Bull)","♉","zodiac","2","Living Wheel","Astrología","Astrológico","tierra fija","sensorialidad","paciencia","sustento","tauro"]', 'Arraigo corporal, sensorialidad fecunda, paciencia rítmica y consolidación de la materia.', 'Terquedad inmovilista, apego posesivo o resistencia al cambio necesario.', '["tierra fija","sensorialidad","paciencia","sustento","tauro"]', 'El suelo fértil donde la semilla echa raíces firmes en el tiempo. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-03', 'livingwheel-zodiac-03-geminis', 'astrological', 'zodiac', 3, '♊', '♊ Géminis (Los Gemelos)', 'Gemini (The Twins)', 'living_wheel', '["♊ Géminis (Los Gemelos)","Géminis (Los Gemelos)","Gemini (The Twins)","♊","zodiac","3","Living Wheel","Astrología","Astrológico","aire mutable","comunicación","curiosidad","dualidad","géminis"]', 'Curiosidad vivaz, puente comunicante, conexión de ideas diversas y agilidad mental.', 'Superficialidad dispersa, charlatanería o incoherencia por no profundizar.', '["aire mutable","comunicación","curiosidad","dualidad","géminis"]', 'El juego del viento que poliniza y vincula lo distante con ligereza. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-04', 'livingwheel-zodiac-04-cancer', 'astrological', 'zodiac', 4, '♋', '♋ Cáncer (El Cangrejo)', 'Cancer (The Crab)', 'living_wheel', '["♋ Cáncer (El Cangrejo)","Cáncer (El Cangrejo)","Cancer (The Crab)","♋","zodiac","4","Living Wheel","Astrología","Astrológico","agua cardinal","hogar","nutrición","pertenencia","cáncer"]', 'Memoria nutricia, cobijo emocional, ternura protectora y fidelidad al origen.', 'Hipersensibilidad defensiva, apego regresivo al pasado o coraza impenetrable.', '["agua cardinal","hogar","nutrición","pertenencia","cáncer"]', 'La marea nutricia y el caparazón que resguarda la vida tierna en gestación. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-05', 'livingwheel-zodiac-05-leo', 'astrological', 'zodiac', 5, '♌', '♌ Leo (El León)', 'Leo (The Lion)', 'living_wheel', '["♌ Leo (El León)","Leo (El León)","Leo (The Lion)","♌","zodiac","5","Living Wheel","Astrología","Astrológico","fuego fijo","corazón","creatividad","brillo personal","leo"]', 'Autoexpresión radiante, generosidad del corazón, dignidad serena y alegría creadora.', 'Orgullo narcisista, demanda ansiosa de aplauso o dramatismo egocéntrico.', '["fuego fijo","corazón","creatividad","brillo personal","leo"]', 'El sol central que irradia calor y soberanía sin pedir permiso para ser. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-06', 'livingwheel-zodiac-06-virgo', 'astrological', 'zodiac', 6, '♍', '♍ Virgo (La Doncella)', 'Virgo (The Virgin)', 'living_wheel', '["♍ Virgo (La Doncella)","Virgo (La Doncella)","Virgo (The Virgin)","♍","zodiac","6","Living Wheel","Astrología","Astrológico","tierra mutable","oficio","pulcritud","discernimiento","virgo"]', 'Discernimiento minucioso, oficio pulcro, servicio con sentido y ecología de recursos.', 'Perfeccionismo paralizante, crítica obsesiva o ansiedad somatizada.', '["tierra mutable","oficio","pulcritud","discernimiento","virgo"]', 'Las manos que seleccionan el grano maduro y cuidan el orden de lo cotidiano. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-07', 'livingwheel-zodiac-07-libra', 'astrological', 'zodiac', 7, '♎', '♎ Libra (La Balanza)', 'Libra (The Scales)', 'living_wheel', '["♎ Libra (La Balanza)","Libra (La Balanza)","Libra (The Scales)","♎","zodiac","7","Living Wheel","Astrología","Astrológico","aire cardinal","vínculo","armonía","belleza","libra"]', 'Búsqueda activa de armonía, reconocimiento del otro, belleza estética y pactos justos.', 'Indecisión por complacer a todos, dependencia de la aprobación o conflicto evitado.', '["aire cardinal","vínculo","armonía","belleza","libra"]', 'El espejo horizontal donde dos voluntades aprenden a dialogar en equilibrio. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-08', 'livingwheel-zodiac-08-escorpio', 'astrological', 'zodiac', 8, '♏', '♏ Escorpio (El Escorpión)', 'Scorpio (The Scorpion)', 'living_wheel', '["♏ Escorpio (El Escorpión)","Escorpio (El Escorpión)","Scorpio (The Scorpion)","♏","zodiac","8","Living Wheel","Astrología","Astrológico","agua fija","transmutación","regeneración","intimidad profunda","escorpio"]', 'Intensidad transformadora, honestidad abisal, transmutación de la sombra y regeneración.', 'Manipulación encubierta, rencor enquistado o autodestrucción obsesiva.', '["agua fija","transmutación","regeneración","intimidad profunda","escorpio"]', 'El crisol donde la materia muere para renacer con plumaje de águila. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-09', 'livingwheel-zodiac-09-sagitario', 'astrological', 'zodiac', 9, '♐', '♐ Sagitario (El Centauro)', 'Sagittarius (The Archer)', 'living_wheel', '["♐ Sagitario (El Centauro)","Sagitario (El Centauro)","Sagittarius (The Archer)","♐","zodiac","9","Living Wheel","Astrología","Astrológico","fuego mutable","sentido","expansión","viaje","sagitario"]', 'Expansión de horizontes, flecha orientada hacia el sentido, confianza y cosmovisión.', 'Dogmatismo sabelotodo, exageración irresponsable o fuga hacia adelante.', '["fuego mutable","sentido","expansión","viaje","sagitario"]', 'La flecha encendida que vuela hacia las estrellas desde el lomo del caballo. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-10', 'livingwheel-zodiac-10-capricornio', 'astrological', 'zodiac', 10, '♑', '♑ Capricornio (La Cabra Marina)', 'Capricorn (The Sea-Goat)', 'living_wheel', '["♑ Capricornio (La Cabra Marina)","Capricornio (La Cabra Marina)","Capricorn (The Sea-Goat)","♑","zodiac","10","Living Wheel","Astrología","Astrológico","tierra cardinal","maestría","tiempo","estructura","capricornio"]', 'Maestría en la cumbre, perseverancia ante la intemperie, responsabilidad y tiempo maduro.', 'Rigidez austera, frialdad burocrática o soledad amarga en la cima.', '["tierra cardinal","maestría","tiempo","estructura","capricornio"]', 'La cabra que asciende paso a paso la roca escarpada hasta alcanzar la cima. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-11', 'livingwheel-zodiac-11-acuario', 'astrological', 'zodiac', 11, '♒', '♒ Acuario (El Aguador)', 'Aquarius (The Water-Bearer)', 'living_wheel', '["♒ Acuario (El Aguador)","Acuario (El Aguador)","Aquarius (The Water-Bearer)","♒","zodiac","11","Living Wheel","Astrología","Astrológico","aire fijo","redes","innovación","libertad","acuario"]', 'Visión comunitaria de vanguardia, fraternidad lúcida, libertad auténtica e innovación.', 'Distanciamiento helado, rebeldía caprichosa sin causa o desconexión del cuerpo.', '["aire fijo","redes","innovación","libertad","acuario"]', 'El ánfora celeste que derrama el éter de la conciencia colectiva del futuro. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-zodiac-12', 'livingwheel-zodiac-12-piscis', 'astrological', 'zodiac', 12, '♓', '♓ Piscis (Los Peces)', 'Pisces (The Fishes)', 'living_wheel', '["♓ Piscis (Los Peces)","Piscis (Los Peces)","Pisces (The Fishes)","♓","zodiac","12","Living Wheel","Astrología","Astrológico","agua mutable","compasión","disolución","misterio","piscis"]', 'Empatía mística cósmica, disolución del ego en la totalidad, compasión y arte trascendente.', 'Evasión victimista, confusión emocional o falta de límites personales.', '["agua mutable","compasión","disolución","misterio","piscis"]', 'El océano primordial donde todos los ríos del zodíaco regresan a fundirse. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-planet-01', 'livingwheel-planet-sun', 'astrological', 'planet', 13, '☉', '☉ El Sol (Luminaria Vital)', 'The Sun (Luminaria)', 'living_wheel', '["☉ El Sol (Luminaria Vital)","El Sol (Luminaria Vital)","The Sun (Luminaria)","☉","planet","13","Living Wheel","Astrología","Astrológico","sol","vitalidad","identidad consciente","centro"]', 'Esencia radiante, centro consciente del ser, vitalidad pura y propósito de vida.', 'Ego inflado, ceguera por encandilamiento o baja energía vital.', '["sol","vitalidad","identidad consciente","centro"]', 'El astro rey en el centro de la órbita de The Living Wheel. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-planet-02', 'livingwheel-planet-moon', 'astrological', 'planet', 14, '☽', '☽ La Luna (Luminaria Nocturna)', 'The Moon (Luminaria)', 'living_wheel', '["☽ La Luna (Luminaria Nocturna)","La Luna (Luminaria Nocturna)","The Moon (Luminaria)","☽","planet","14","Living Wheel","Astrología","Astrológico","luna","emoción","ritmo corporal","inconsciente"]', 'Mundo emocional, cuerpo sensible, memoria celular, ritmos biológicos e intuición.', 'Oscilación anímica desbordada, apego infantil o inseguridad nocturna.', '["luna","emoción","ritmo corporal","inconsciente"]', 'El espejo de plata que recibe y refleja la luz en fases de marea viva. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-planet-03', 'livingwheel-planet-mercury', 'astrological', 'planet', 15, '☿', '☿ Mercurio (El Enlace Alado)', 'Mercury (The Messenger)', 'living_wheel', '["☿ Mercurio (El Enlace Alado)","Mercurio (El Enlace Alado)","Mercury (The Messenger)","☿","planet","15","Living Wheel","Astrología","Astrológico","mercurio","mente","comunicación","aprendizaje","enlace"]', 'Mente articuladora, lenguaje claro, capacidad de aprendizaje, conexión y traducción.', 'Sobrecarga de estímulos, nerviosismo mental o comunicación engañosa.', '["mercurio","mente","comunicación","aprendizaje","enlace"]', 'El caduceo alado que une los dos hemisferios del conocimiento. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-planet-04', 'livingwheel-planet-venus', 'astrological', 'planet', 16, '♀', '♀ Venus (El Goce y la Belleza)', 'Venus (Desire & Beauty)', 'living_wheel', '["♀ Venus (El Goce y la Belleza)","Venus (El Goce y la Belleza)","Venus (Desire & Beauty)","♀","planet","16","Living Wheel","Astrología","Astrológico","venus","belleza","valor personal","deseo","goce"]', 'Valor personal, capacidad de deleite sensorial, atracción magnética, armonía y estética.', 'Banalidad insatisfecha, mendicidad afectiva o derroche estéril.', '["venus","belleza","valor personal","deseo","goce"]', 'El espejo de cobre y la flor que atrae sin forzar la marcha del cosmos. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-planet-05', 'livingwheel-planet-mars', 'astrological', 'planet', 17, '♂', '♂ Marte (El Impulso Conquistador)', 'Mars (Action & Drive)', 'living_wheel', '["♂ Marte (El Impulso Conquistador)","Marte (El Impulso Conquistador)","Mars (Action & Drive)","♂","planet","17","Living Wheel","Astrología","Astrológico","marte","acción","fuerza motriz","asertividad","deseo motor"]', 'Energía asertiva, valentía para abrir brecha, defensa firme y pasión activa.', 'Ira desmedida, choque violento o impotencia por reprimir la acción.', '["marte","acción","fuerza motriz","asertividad","deseo motor"]', 'La lanza forjada al rojo vivo que abre camino en la roca. (Mazo The Living Wheel Astrológico).');
