INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-planet-08', 'livingwheel-planet-uranus', 'astrological', 'planet', 20, '♅', '♅ Urano (El Despertar)', 'Uranus (Awakening & Shift)', 'living_wheel', '["♅ Urano (El Despertar)","Urano (El Despertar)","Uranus (Awakening & Shift)","♅","planet","20","Living Wheel","Astrología","Astrológico","urano","despertar","liberación","originalidad","relámpago"]', 'Salto cuántico de conciencia, liberación súbita de ataduras, originalidad e intuición relámpago.', 'Rebeldía caótica, corte traumático o desconexión emocional fría.', '["urano","despertar","liberación","originalidad","relámpago"]', 'El relámpago que rompe el cielo cerrado e ilumina la verdad en un destello. (Mazo The Living Wheel Astrológico).');
