INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-02', 'livingwheel-house-02-recursos', 'astrological', 'house', 24, 'H2', 'H2 Casa 2: Recursos y Autoestima', '2nd House: Resources & Values', 'living_wheel', '["H2 Casa 2: Recursos y Autoestima","Casa 2: Recursos y Autoestima","2nd House: Resources & Values","H2","house","24","Living Wheel","Astrología","Astrológico","casa 2","recursos","autoestima","finanzas","materia"]', 'Sustento material, dones y talentos propios, autovaloración y relación saludable con el dinero.', 'Inseguridad de carencia, avaricia temerosa o malbaratar el propio talento.', '["casa 2","recursos","autoestima","finanzas","materia"]', 'El granero íntimo donde se guarda la provisión para la travesía. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-03', 'livingwheel-house-03-comunicacion', 'astrological', 'house', 25, 'H3', 'H3 Casa 3: Entorno y Comunicación', '3rd House: Environment & Mind', 'living_wheel', '["H3 Casa 3: Entorno y Comunicación","Casa 3: Entorno y Comunicación","3rd House: Environment & Mind","H3","house","25","Living Wheel","Astrología","Astrológico","casa 3","comunicación","hermanos","entorno cercano","aprendizaje"]', 'Hermanos, vecinos, traslados cortos, aprendizaje concreto y diálogo cotidiano en el entorno.', 'Ruidos de comunicación, malentendidos con pares cercanos o dispersión nerviosa.', '["casa 3","comunicación","hermanos","entorno cercano","aprendizaje"]', 'El cruce de caminos donde se intercambian noticias y oficios con el vecino. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-04', 'livingwheel-house-04-hogar-raices', 'astrological', 'house', 26, 'H4', 'H4 Casa 4: El Fondo del Cielo (Raíces)', '4th House: The Imum Coeli (Roots)', 'living_wheel', '["H4 Casa 4: El Fondo del Cielo (Raíces)","Casa 4: El Fondo del Cielo (Raíces)","4th House: The Imum Coeli (Roots)","H4","house","26","Living Wheel","Astrología","Astrológico","casa 4","fondo del cielo","hogar","raíces","linaje"]', 'Hogar, intimidad familiar, linaje ancestral, base psíquica profunda y refugio íntimo.', 'Herida infantil no resuelta, desarraigo incómodo o asfixia en el mandato familiar.', '["casa 4","fondo del cielo","hogar","raíces","linaje"]', 'Los cimientos del hogar bajo el suelo donde reposa la memoria familiar. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-05', 'livingwheel-house-05-creatividad-amor', 'astrological', 'house', 27, 'H5', 'H5 Casa 5: Goce, Amor y Creación', '5th House: Pleasure & Creation', 'living_wheel', '["H5 Casa 5: Goce, Amor y Creación","Casa 5: Goce, Amor y Creación","5th House: Pleasure & Creation","H5","house","27","Living Wheel","Astrología","Astrológico","casa 5","creatividad","hijos","romance","goce lúdico"]', 'Juego libre, pasiones creativas, romances vivificantes, fertilidad, hijos y entusiasmo lúdico.', 'Bloqueo expresivo, adicción al juego o drama ególatra en el amor.', '["casa 5","creatividad","hijos","romance","goce lúdico"]', 'El escenario radiante donde el corazón sale a cantar su obra sin miedo. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-06', 'livingwheel-house-06-salud-servicio', 'astrological', 'house', 28, 'H6', 'H6 Casa 6: Hábitos, Rutina y Salud', '6th House: Service & Health', 'living_wheel', '["H6 Casa 6: Hábitos, Rutina y Salud","Casa 6: Hábitos, Rutina y Salud","6th House: Service & Health","H6","house","28","Living Wheel","Astrología","Astrológico","casa 6","salud","rutina","oficio","servicio"]', 'Cuidado amoroso del cuerpo, oficio diario bien hecho, nutrición, hábitos sanos y servicio útil.', 'Hipocondría, sobrecarga laboral estresante o rutina vaciada de sentido.', '["casa 6","salud","rutina","oficio","servicio"]', 'El telar cotidiano donde la salud se teje en cada respiración consciente. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-07', 'livingwheel-house-07-descendente-pareja', 'astrological', 'house', 29, 'H7', 'H7 Casa 7: El Descendente (El Otro)', '7th House: The Descendant (Others)', 'living_wheel', '["H7 Casa 7: El Descendente (El Otro)","Casa 7: El Descendente (El Otro)","7th House: The Descendant (Others)","H7","house","29","Living Wheel","Astrología","Astrológico","casa 7","descendente","pareja","socios","acuerdos"]', 'El encuentro cara a cara con el tú: pareja, sociedades, acuerdos firmes y espejo vincular.', 'Proyección de la sombra en el otro, conflicto abierto o codependencia disfuncional.', '["casa 7","descendente","pareja","socios","acuerdos"]', 'El umbral del poniente donde el yo se inclina con respeto ante el misterio del tú. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-08', 'livingwheel-house-08-intimidad-muerte', 'astrological', 'house', 30, 'H8', 'H8 Casa 8: Transformación e Intimidad', '8th House: Metamorphosis & Depths', 'living_wheel', '["H8 Casa 8: Transformación e Intimidad","Casa 8: Transformación e Intimidad","8th House: Metamorphosis & Depths","H8","house","30","Living Wheel","Astrología","Astrológico","casa 8","intimidad profunda","recursos compartidos","crisis","muerte"]', 'Fusión íntima profunda, recursos compartidos, herencias kármicas, crisis que regenera y transmutación.', 'Lucha soterrada de poder financiero, celos destructivos o miedo al abismo.', '["casa 8","intimidad profunda","recursos compartidos","crisis","muerte"]', 'La cueva de la alquimia donde los dos se desnudan hasta el hueso para fusionarse. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-09', 'livingwheel-house-09-filosofia-viajes', 'astrological', 'house', 31, 'H9', 'H9 Casa 9: Filosofía y Grandes Viajes', '9th House: Philosophy & Journeys', 'living_wheel', '["H9 Casa 9: Filosofía y Grandes Viajes","Casa 9: Filosofía y Grandes Viajes","9th House: Philosophy & Journeys","H9","house","31","Living Wheel","Astrología","Astrológico","casa 9","filosofía","viajes largos","cosmovisión","estudios superiores"]', 'Búsqueda honesta de la verdad, estudios superiores, viajes transculturales y cosmovisión viva.', 'Dogmatismo fanático, soberbia académica o fuga en teorías abstractas.', '["casa 9","filosofía","viajes largos","cosmovisión","estudios superiores"]', 'El faro en el cabo de ultramar que orienta el navío hacia mares inexplorados. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-10', 'livingwheel-house-10-medio-cielo-vocacion', 'astrological', 'house', 32, 'H10', 'H10 Casa 10: El Medio Cielo (Vocación)', '10th House: The Midheaven (Vocation)', 'living_wheel', '["H10 Casa 10: El Medio Cielo (Vocación)","Casa 10: El Medio Cielo (Vocación)","10th House: The Midheaven (Vocation)","H10","house","32","Living Wheel","Astrología","Astrológico","casa 10","medio cielo","vocación","logro","reputación pública"]', 'Llamado vocacional en el mundo, reputación pública sólida, logros visibles y legado maduro.', 'Éxito vacío que cuesta la salud, desprestigio público o frustración con la jerarquía.', '["casa 10","medio cielo","vocación","logro","reputación pública"]', 'El punto cenital donde el sol de la tarde ilumina la obra culminada ante la comunidad. (Mazo The Living Wheel Astrológico).');
