INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-house-12', 'livingwheel-house-12-inconsciente-retiro', 'astrological', 'house', 34, 'H12', 'H12 Casa 12: Inconsciente y Trascendencia', '12th House: Transcendence & Silence', 'living_wheel', '["H12 Casa 12: Inconsciente y Trascendencia","Casa 12: Inconsciente y Trascendencia","12th House: Transcendence & Silence","H12","house","34","Living Wheel","Astrología","Astrológico","casa 12","inconsciente","retiro","sanación kármica","silencio sagrado"]', 'Sanación del karma ancestral, retiro silencioso fecundo, disolución del ego y conexión cósmica.', 'Autoboicot involuntario, encierro melancólico o evasión de la realidad terrenal.', '["casa 12","inconsciente","retiro","sanación kármica","silencio sagrado"]', 'El santuario secreto en la niebla donde el alma conversa a solas con el Creador. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-01', 'livingwheel-elem-fuego', 'astrological', 'element', 35, '🜂', '🜂 Elemento Fuego (Vitalidad e Impulso)', 'Fire Element (Spirit & Will)', 'living_wheel', '["🜂 Elemento Fuego (Vitalidad e Impulso)","Elemento Fuego (Vitalidad e Impulso)","Fire Element (Spirit & Will)","🜂","element","35","Living Wheel","Astrología","Astrológico","fuego","voluntad","pasión","impulso vital","espíritu"]', 'Fuego primordial: pasión, coraje, entusiasmo vivificante, calor y voluntad activa.', 'Quemazón por exceso, impaciencia destructiva o frialdad por fuego apagado.', '["fuego","voluntad","pasión","impulso vital","espíritu"]', 'La llama primordial de The Living Wheel que enciende los mundos. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-02', 'livingwheel-elem-tierra', 'astrological', 'element', 36, '🜃', '🜃 Elemento Tierra (Forma y Materia)', 'Earth Element (Matter & Body)', 'living_wheel', '["🜃 Elemento Tierra (Forma y Materia)","Elemento Tierra (Forma y Materia)","Earth Element (Matter & Body)","🜃","element","36","Living Wheel","Astrología","Astrológico","tierra","materia","cuerpo","arraigo","concreción"]', 'Tierra sagrada: concreción, arraigo corporal, tiempo paciente, forma y sustento tangible.', 'Pesadez inerte, materialismo ciego o miedo paralizante a la escasez.', '["tierra","materia","cuerpo","arraigo","concreción"]', 'El suelo arcilloso que sostiene los pasos y modela la vasija viva. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-03', 'livingwheel-elem-aire', 'astrological', 'element', 37, '🜁', '🜁 Elemento Aire (Mente y Relación)', 'Air Element (Mind & Breath)', 'living_wheel', '["🜁 Elemento Aire (Mente y Relación)","Elemento Aire (Mente y Relación)","Air Element (Mind & Breath)","🜁","element","37","Living Wheel","Astrología","Astrológico","aire","mente","pensamiento","relación","perspectiva"]', 'Aire lúcido: perspectiva amplia, vuelo del pensamiento, diálogo horizontal y respiración libre.', 'Frialdad hiperracional, tormenta de ideas sin raíz o asfixia comunicacional.', '["aire","mente","pensamiento","relación","perspectiva"]', 'El aliento invisible que circula entre los árboles y transporta el canto. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-04', 'livingwheel-elem-agua', 'astrological', 'element', 38, '🜄', '🜄 Elemento Agua (Emoción y Alma)', 'Water Element (Soul & Flow)', 'living_wheel', '["🜄 Elemento Agua (Emoción y Alma)","Elemento Agua (Emoción y Alma)","Water Element (Soul & Flow)","🜄","element","38","Living Wheel","Astrología","Astrológico","agua","emoción","alma","fluidez","empatía"]', 'Agua primordial: fluidez sensible, empatía profunda, resonancia afectiva y memoria del alma.', 'Inundación emocional incontrolada, estancamiento pantanoso o aridez defensiva.', '["agua","emoción","alma","fluidez","empatía"]', 'El manantial cristalino que brota de la gruta y calma la sed del peregrino. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-05', 'livingwheel-modalidad-cardinal', 'astrological', 'element', 39, 'CARD', 'CARD Modalidad Cardinal (El Inicio)', 'Cardinal Modality (Initiation)', 'living_wheel', '["CARD Modalidad Cardinal (El Inicio)","Modalidad Cardinal (El Inicio)","Cardinal Modality (Initiation)","CARD","element","39","Living Wheel","Astrología","Astrológico","cardinal","inicio","dirección","impulso","liderazgo"]', 'Impulso emprendedor, capacidad de marcar rumbo, chispa que arranca un nuevo ciclo.', 'Tensión de arranque forzado, apresuramiento o dificultad para sostener lo comenzado.', '["cardinal","inicio","dirección","impulso","liderazgo"]', 'El equinoccio y el solsticio que marcan el cambio de estación en la rueda. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-06', 'livingwheel-modalidad-fija', 'astrological', 'element', 40, 'FIX', 'FIX Modalidad Fija (La Consolidación)', 'Fixed Modality (Stabilization)', 'living_wheel', '["FIX Modalidad Fija (La Consolidación)","Modalidad Fija (La Consolidación)","Fixed Modality (Stabilization)","FIX","element","40","Living Wheel","Astrología","Astrológico","fijo","estabilidad","arraigo","constancia","consolidación"]', 'Lealtad a la forma, constancia inquebrantable, consolidación y perseverancia madura.', 'Rigidez obstinada, miedo al cambio o estancamiento por aferramiento.', '["fijo","estabilidad","arraigo","constancia","consolidación"]', 'El pilar central del templo que sostiene el techo durante la tormenta. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-07', 'livingwheel-modalidad-mutable', 'astrological', 'element', 41, 'MUT', 'MUT Modalidad Mutable (La Transición)', 'Mutable Modality (Adaptation)', 'living_wheel', '["MUT Modalidad Mutable (La Transición)","Modalidad Mutable (La Transición)","Mutable Modality (Adaptation)","MUT","element","41","Living Wheel","Astrología","Astrológico","mutable","adaptación","cambio","flexibilidad","síntesis"]', 'Flexibilidad inteligente, adaptación a los vientos cambiantes, síntesis y aprendizaje vivo.', 'Inconstancia volátil, dispersión de energías o pérdida de centro.', '["mutable","adaptación","cambio","flexibilidad","síntesis"]', 'El cauce sinuoso del río que bordea las piedras sin quebrar su curso. (Mazo The Living Wheel Astrológico).');
