INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-09', 'livingwheel-nodo-sur', 'astrological', 'element', 43, '☋', '☋ Nodo Sur Lunar (La Memoria Kármica)', 'South Node (Ancestral Memory)', 'living_wheel', '["☋ Nodo Sur Lunar (La Memoria Kármica)","Nodo Sur Lunar (La Memoria Kármica)","South Node (Ancestral Memory)","☋","element","43","Living Wheel","Astrología","Astrológico","nodo sur","karma","memoria ancestral","talento innato","pasado"]', 'Dones heredados, maestría natural forjada en vidas pasadas, plataforma de seguridad.', 'Zona de confort paralizante, estancamiento en viejos patrones tóxicos superados.', '["nodo sur","karma","memoria ancestral","talento innato","pasado"]', 'El cofre de reliquias familiares que honra lo vivido sin anclar el barco en el puerto. (Mazo The Living Wheel Astrológico).');
