INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-11', 'livingwheel-lilith-luna-negra', 'astrological', 'element', 45, '⚸', '⚸ Lilith (La Luna Negra)', 'Black Moon Lilith (Wild Truth)', 'living_wheel', '["⚸ Lilith (La Luna Negra)","Lilith (La Luna Negra)","Black Moon Lilith (Wild Truth)","⚸","element","45","Living Wheel","Astrología","Astrológico","lilith","luna negra","soberanía","salvaje","verdad visceral"]', 'Soberanía salvaje, verdad instintiva que no se arrodilla ante mandatos falsos, libertad desnuda.', 'Rebeldía destructiva, rechazo al vínculo sano o castigo a la propia pulsión vital.', '["lilith","luna negra","soberanía","salvaje","verdad visceral"]', 'La mujer que abandona el paraíso sumiso para habitar el desierto en soberanía plena. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-12', 'livingwheel-parte-fortuna', 'astrological', 'element', 46, '⊗', '⊗ Parte de la Fortuna (Armonía Mundana)', 'Part of Fortune (Joy & Flow)', 'living_wheel', '["⊗ Parte de la Fortuna (Armonía Mundana)","Parte de la Fortuna (Armonía Mundana)","Part of Fortune (Joy & Flow)","⊗","element","46","Living Wheel","Astrología","Astrológico","parte de la fortuna","sincronicidad","felicidad terrenal","plenitud"]', 'Punto de máxima sincronicidad armónica entre cuerpo, alma y mente; felicidad tangible.', 'Desalineación de prioridades, desconexión de lo que realmente nutre la alegría propia.', '["parte de la fortuna","sincronicidad","felicidad terrenal","plenitud"]', 'La cornucopia de oro en el cruce exacto de las tres luminarias de la carta natal. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-13', 'livingwheel-vertice-destino', 'astrological', 'element', 47, 'Vx', 'Vx El Vértice (El Punto del Destino)', 'The Vertex (Destined Encounters)', 'living_wheel', '["Vx El Vértice (El Punto del Destino)","El Vértice (El Punto del Destino)","The Vertex (Destined Encounters)","Vx","element","47","Living Wheel","Astrología","Astrológico","vértice","destino kármico","sincronicidad","punto de giro","encuentro"]', 'Encuentros kármicos predestinados, puntos de inflexión inesperados y sincronicidades mayores.', 'Resistencia a la encrucijada del destino o temor ante la magnitud del giro.', '["vértice","destino kármico","sincronicidad","punto de giro","encuentro"]', 'La puerta lateral que se abre de golpe en la pared cuando menos se la esperaba. (Mazo The Living Wheel Astrológico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('lw-elem-14', 'livingwheel-rueda-cosmica', 'astrological', 'element', 48, '☸', '☸ The Living Wheel (La Rueda Astrológica)', 'The Living Wheel (Cosmic Mandala)', 'living_wheel', '["☸ The Living Wheel (La Rueda Astrológica)","The Living Wheel (La Rueda Astrológica)","The Living Wheel (Cosmic Mandala)","☸","element","48","Living Wheel","Astrología","Astrológico","living wheel","mandala cósmico","integración astrológica","rueda de la vida"]', 'Integración total del mapa cósmico, síntesis viva de los 12 signos, casas y planetas en marcha.', 'Fragmentación de la mirada, incapacidad para ver el mandala completo de la situación.', '["living wheel","mandala cósmico","integración astrológica","rueda de la vida"]', 'La rueda cósmica viviente que respira al unísono con el cielo y la tierra. (Mazo The Living Wheel Astrológico).');
