INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-13', 'marseille-13-larcane-sans-nom', 'major', NULL, 13, 'XIII', 'El Arcano Sin Nombre (L''Arcane sans nom)', 'The Nameless Arcana (Death)', 'marseille', '["El Arcano Sin Nombre (L''Arcane sans nom)","L''Arcane sans nom","The Nameless Arcana (Death)","XIII","13","Marsella","Marseille","siega","transmutación","esencia","sin nombre"]', 'Transformación radical sin rótulo, siega de lo caduco, liberación del hueso esencial.', 'Resistencia aterrada al cambio, agonía prolongada o duelo no resuelto.', '["siega","transmutación","esencia","sin nombre"]', 'El esqueleto rojo sobre la tierra negra con guadaña de hoja dorada. (Tarot de Marsella histórico).');
