INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-15', 'marseille-15-le-diable', 'major', NULL, 15, 'XV', 'El Diablo (Le Diable)', 'The Devil', 'marseille', '["El Diablo (Le Diable)","Le Diable","The Devil","XV","15","Marsella","Marseille","telúrico","magnetismo","pulsión","antorcha"]', 'Fuerza telúrica, pulsión creativa abismal, magnetismo erótico y riquezas del fondo.', 'Tiranía de las pasiones ciegas, engaño o servidumbre voluntaria.', '["telúrico","magnetismo","pulsión","antorcha"]', 'La figura alada con antorcha sobre el pedestal al que están atados dos diablillos. (Tarot de Marsella histórico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-16', 'marseille-16-la-maison-dieu', 'major', NULL, 16, 'XVI', 'La Casa Dios (La Maison Dieu)', 'The House of God (The Tower)', 'marseille', '["La Casa Dios (La Maison Dieu)","La Maison Dieu","The House of God (The Tower)","XVI","16","Marsella","Marseille","apertura","descompresión","templo","relámpago"]', 'Apertura forzosa del templo cerrado, festejo terrenal tras la descompresión, revelación.', 'Colapso traumático, orgullo herido o encierro en murallas quebradas.', '["apertura","descompresión","templo","relámpago"]', 'La torre descoronada por la llama y las dos figuras danzando con las manos en el suelo. (Tarot de Marsella histórico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-17', 'marseille-17-letoile', 'major', NULL, 17, 'XVII', 'La Estrella (L''Étoile)', 'The Star', 'marseille', '["La Estrella (L''Étoile)","L''Étoile","The Star","XVII","17","Marsella","Marseille","propio lugar","purificación","vertido","firmamento"]', 'Hallar el propio lugar en la tierra, purificación generosa sin reserva, armonía cósmica.', 'Desolación, sentimiento de desarraigo o derroche estéril de dones.', '["propio lugar","purificación","vertido","firmamento"]', 'La mujer arrodillada que nutre la tierra y el agua bajo las ocho estrellas. (Tarot de Marsella histórico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-18', 'marseille-18-la-lune', 'major', NULL, 18, 'XVIII', 'La Luna (La Lune)', 'The Moon', 'marseille', '["La Luna (La Lune)","La Lune","The Moon","XVIII","18","Marsella","Marseille","poesía nocturna","inconsciente","mareas","origen"]', 'Poesía del inconsciente, magnetismo nocturno, aguas nutricias y receptividad matriarcal.', 'Pesadilla ilusoria, depresión melancólica o pérdida en el laberinto.', '["poesía nocturna","inconsciente","mareas","origen"]', 'Las gotas que ascienden hacia la luna mientras los cánidos custodian las torres. (Tarot de Marsella histórico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-19', 'marseille-19-le-soleil', 'major', NULL, 19, 'XIX', 'El Sol (Le Soleil)', 'The Sun', 'marseille', '["El Sol (Le Soleil)","Le Soleil","The Sun","XIX","19","Marsella","Marseille","fraternidad","calor","claridad","luz compartida"]', 'Fraternidad amorosa, luz fecunda compartida, lucidez fraterna y éxito claro.', 'Desencuentro entre pares, ceguera por encandilamiento o aridez afectiva.', '["fraternidad","calor","claridad","luz compartida"]', 'Los dos gemelos abrazados bajo la lluvia de dones dorados del gran sol. (Tarot de Marsella histórico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-20', 'marseille-20-le-jugement', 'major', NULL, 20, 'XX', 'El Juicio (Le Jugement)', 'Judgement', 'marseille', '["El Juicio (Le Jugement)","Le Jugement","Judgement","XX","20","Marsella","Marseille","resurrección","trompeta","nueva vida","reunión"]', 'Resurrección consciente, llamado que une pasado, presente y futuro en una nueva vida.', 'Sordera al llamado vocacional, resistencia a renacer o juicio moralizante.', '["resurrección","trompeta","nueva vida","reunión"]', 'El ángel con la bandera de la cruz sonando la trompeta ante las tres figuras que emergen. (Tarot de Marsella histórico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('marseille-major-21', 'marseille-21-le-monde', 'major', NULL, 21, 'XXI', 'El Mundo (Le Monde)', 'The World', 'marseille', '["El Mundo (Le Monde)","Le Monde","The World","XXI","21","Marsella","Marseille","plenitud","danza","guirnalda","realización"]', 'Plenitud realizada, danza en el centro de la creación, totalidad viva y armónica.', 'Imposibilidad de coronar la obra, encierro en la propia cáscara o aislamiento.', '["plenitud","danza","guirnalda","realización"]', 'La doncella en la guirnalda rodeada por los cuatro evangelistas en las esquinas. (Tarot de Marsella histórico).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-00', '00-el-loco', 'major', NULL, 0, '0', 'El Loco', 'The Fool', 'rws', '["El Loco","The Fool","Fool","Loco","0","00","inicio","disponibilidad","umbral","espontaneidad"]', 'Apertura radical, inicio sin garantías, disponibilidad ante la experiencia desconocida.', 'Impulsividad desorientada, postergación del primer paso por vértigo o dispersión.', '["inicio","disponibilidad","umbral","espontaneidad"]', 'El caminante en el borde antes de fijar rumbo.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-01', '01-el-mago', 'major', NULL, 1, 'I', 'El Mago', 'The Magician', 'rws', '["El Mago","The Magician","Magician","Mago","I","1","voluntad","oficio","instrumentos","articulación"]', 'Disposición de recursos concretos sobre la mesa, iniciativa consciente, destreza técnica.', 'Habilidad fragmentada, exceso de artificio o duda frente a las herramientas propias.', '["voluntad","oficio","instrumentos","articulación"]', 'La mesa dispuesta con los cuatro elementos listos para obrar.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('wands-01', 'bastos-01-as', 'minor', 'wands', 1, '1', 'As de Bastos', 'Ace of Wands', 'rws', '["As de Bastos","Ace of Wands","1 de Bastos","1 of Wands","Ace of Coins","1 of Coins","As Bastos","Ace Wands","Wands","Wand","Rods","Staves","Bastos","1","chispa","impulso","origen"]', 'Chispa inicial de proyecto, vitalidad naciente y deseo de emprender.', 'Impulso contenido, vacilación al arrancar o energía dispersa.', '["chispa","impulso","origen"]', 'Impulso creativo, deseo, acción y fuego vital · Grado As.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('cups-01', 'copas-01-as', 'minor', 'cups', 1, '1', 'As de Copas', 'Ace of Cups', 'rws', '["As de Copas","Ace of Cups","1 de Copas","1 of Cups","Ace of Coins","1 of Coins","As Copas","Ace Cups","Cups","Cup","Chalices","Copas","1","apertura","afecto","manantial"]', 'Receptividad afectiva plena, apertura cordial, renovación sensible.', 'Contención emocional por cautela o dificultad para recibir afecto.', '["apertura","afecto","manantial"]', 'Afectividad, receptividad, vínculo, memoria e imaginación · Grado As.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('swords-01', 'espadas-01-as', 'minor', 'swords', 1, '1', 'As de Espadas', 'Ace of Swords', 'rws', '["As de Espadas","Ace of Swords","1 de Espadas","1 of Swords","Ace of Coins","1 of Coins","As Espadas","Ace Swords","Swords","Sword","Blades","Espadas","1","lucidez","corte","verdad"]', 'Claridad incisiva, comprensión repentina que corta la niebla mental.', 'Crueldad verbal, hiperracionalización o juicio precipitado.', '["lucidez","corte","verdad"]', 'Pensamiento, lenguaje, delimitación, verdad y discernimiento · Grado As.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('pentacles-01', 'oros-01-as', 'minor', 'pentacles', 1, '1', 'As de Oros', 'Ace of Pentacles', 'rws', '["As de Oros","Ace of Pentacles","1 de Oros","1 of Pentacles","Ace of Coins","1 of Coins","As Oros","Ace Pentacles","Pentacles","Pentacle","Coins","Coin","Disks","Oros","Monedas","1","semilla","oportunidad concreta","sustento"]', 'Semilla tangible, oportunidad material concreta que merece cultivo paciente.', 'Recurso desaprovechado, codicia prematura o falta de arraigo físico.', '["semilla","oportunidad concreta","sustento"]', 'Materia, cuerpo, recursos concretos, tiempo y trabajo sostenido · Grado As.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-02', '02-la-sacerdotisa', 'major', NULL, 2, 'II', 'La Sacerdotisa', 'The High Priestess', 'rws', '["La Sacerdotisa","The High Priestess","High Priestess","Priestess","Sacerdotisa","Papisa","II","2","silencio","reserva","estudio","gestación"]', 'Escucha silenciosa, gestación interna, estudio paciente y reserva necesaria.', 'Silencio defensivo, desconexión de la intuición o lectura superficial del momento.', '["silencio","reserva","estudio","gestación"]', 'El velo entre dos columnas y el libro reposando en el regazo.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('wands-02', 'bastos-02-dos', 'minor', 'wands', 2, '2', 'Dos de Bastos', 'Two of Wands', 'rws', '["Dos de Bastos","Two of Wands","2 de Bastos","2 of Wands","Two of Coins","2 of Coins","Dos Bastos","Two Wands","Wands","Wand","Rods","Staves","Bastos","2","horizonte","proyección","umbral"]', 'Contemplación de horizonte, planificación antes de salir del terreno conocido.', 'Temor a ampliar el radio de acción o planes sin ejecución.', '["horizonte","proyección","umbral"]', 'Impulso creativo, deseo, acción y fuego vital · Grado Dos.');
