INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('swords-13', 'espadas-13-reina', 'minor', 'swords', 13, 'RE', 'Reina de Espadas', 'Queen of Swords', 'rws', '["Reina de Espadas","Queen of Swords","13 de Espadas","13 of Swords","Queen of Coins","13 of Coins","Reina Espadas","Queen Swords","Swords","Sword","Blades","Espadas","13","autonomía de juicio","sobriedad","claridad ética"]', 'Independencia de criterio, juicio sobrio forjado en la experiencia, honestidad directa.', 'Amargura defensiva, corte insensible o aislamiento escéptico.', '["autonomía de juicio","sobriedad","claridad ética"]', 'Pensamiento, lenguaje, delimitación, verdad y discernimiento · Grado Reina.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('pentacles-13', 'oros-13-reina', 'minor', 'pentacles', 13, 'RE', 'Reina de Oros', 'Queen of Pentacles', 'rws', '["Reina de Oros","Queen of Pentacles","13 de Oros","13 of Pentacles","Queen of Coins","13 of Coins","Reina Oros","Queen Pentacles","Pentacles","Pentacle","Coins","Coin","Disks","Oros","Monedas","13","sustento","presencia corporal","hospitalidad"]', 'Cuidado generoso de lo concreto, hospitalidad terrenal y sentido práctico.', 'Autoabandono corporal por sostener a otros o control doméstico.', '["sustento","presencia corporal","hospitalidad"]', 'Materia, cuerpo, recursos concretos, tiempo y trabajo sostenido · Grado Reina.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-14', '14-la-templanza', 'major', NULL, 14, 'XIV', 'La Templanza', 'Temperance', 'rws', '["La Templanza","Temperance","Templanza","XIV","14","armonía","medida","fluidez","integración"]', 'Alquimia sutil, integración paciente de contrarios, dosificación sabia del caudal vital.', 'Falta de medida, exceso o precipitación que desvirtúa la mezcla en proceso.', '["armonía","medida","fluidez","integración"]', 'El trasvase constante de un ánfora a otra sin que se pierda una sola gota.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('wands-14', 'bastos-14-rey', 'minor', 'wands', 14, 'RE', 'Rey de Bastos', 'King of Wands', 'rws', '["Rey de Bastos","King of Wands","14 de Bastos","14 of Wands","King of Coins","14 of Coins","Rey Bastos","King Wands","Wands","Wand","Rods","Staves","Bastos","14","visión","dirección","iniciativa"]', 'Visión directiva, liderazgo generoso que orienta proyectos de largo aliento.', 'Autoritarismo impaciente o visión desligada del cuidado cotidiano.', '["visión","dirección","iniciativa"]', 'Impulso creativo, deseo, acción y fuego vital · Grado Rey.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('cups-14', 'copas-14-rey', 'minor', 'cups', 14, 'RE', 'Rey de Copas', 'King of Cups', 'rws', '["Rey de Copas","King of Cups","14 de Copas","14 of Cups","King of Coins","14 of Coins","Rey Copas","King Cups","Cups","Cup","Chalices","Copas","14","templanza","madurez emocional","serenidad"]', 'Madurez afectiva, serenidad para sostener tormentas ajenas sin desbordar.', 'Manipulación emocional sutil o distanciamiento afectivo protector.', '["templanza","madurez emocional","serenidad"]', 'Afectividad, receptividad, vínculo, memoria e imaginación · Grado Rey.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('swords-14', 'espadas-14-rey', 'minor', 'swords', 14, 'RE', 'Rey de Espadas', 'King of Swords', 'rws', '["Rey de Espadas","King of Swords","14 de Espadas","14 of Swords","King of Coins","14 of Coins","Rey Espadas","King Swords","Swords","Sword","Blades","Espadas","14","ecuanimidad","justicia mental","visión ética"]', 'Autoridad intelectual ética, capacidad para legislar con justicia y ecuanimidad.', 'Tiranía lógica, distanciamiento deshumanizado o frialdad burocrática.', '["ecuanimidad","justicia mental","visión ética"]', 'Pensamiento, lenguaje, delimitación, verdad y discernimiento · Grado Rey.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('pentacles-14', 'oros-14-rey', 'minor', 'pentacles', 14, 'RE', 'Rey de Oros', 'King of Pentacles', 'rws', '["Rey de Oros","King of Pentacles","14 de Oros","14 of Pentacles","King of Coins","14 of Coins","Rey Oros","King Pentacles","Pentacles","Pentacle","Coins","Coin","Disks","Oros","Monedas","14","solvencia","administración","firmeza"]', 'Administración serena y fecunda de recursos, solvencia puesta al servicio.', 'Materialismo estrecho, terquedad conservadora o temor al riesgo medido.', '["solvencia","administración","firmeza"]', 'Materia, cuerpo, recursos concretos, tiempo y trabajo sostenido · Grado Rey.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-15', '15-el-diablo', 'major', NULL, 15, 'XV', 'El Diablo', 'The Devil', 'rws', '["El Diablo","The Devil","Devil","Diablo","XV","15","atadura","pulsión","sombra","magnetismo"]', 'Reconocimiento de las ataduras materiales, pulsión primaria, sombra y fascinación magnética.', 'Liberación gradual de dependencias, lucidez ante la trampa o ilusión de servidumbre.', '["atadura","pulsión","sombra","magnetismo"]', 'La cadena suelta al cuello que solo aprisiona mientras no se intente descolgar.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-16', '16-la-torre', 'major', NULL, 16, 'XVI', 'La Torre', 'The Tower', 'rws', '["La Torre","The Tower","Tower","Torre","XVI","16","quiebre","revelación","liberación","ruptura"]', 'Derrumbe súbito de lo edificado sobre fundamentos falsos, revelación intempestiva.', 'Colapso demorado, temor al desarraigo o reconstrucción precipitada sobre escombros.', '["quiebre","revelación","liberación","ruptura"]', 'El rayo que quiebra la corona de almenas y abre el cielo clausurado.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-17', '17-la-estrella', 'major', NULL, 17, 'XVII', 'La Estrella', 'The Star', 'rws', '["La Estrella","The Star","Star","Estrella","XVII","17","esperanza","claridad","entrega","sencillez"]', 'Esperanza serena, entrega sin cálculo de las aguas propias, generosidad transparente.', 'Pérdida momentánea de fe, desconexión de la propia fuente o idealismo estéril.', '["esperanza","claridad","entrega","sencillez"]', 'La mujer desnuda bajo el firmamento que vierte el agua en la tierra y en el río.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-18', '18-la-luna', 'major', NULL, 18, 'XVIII', 'La Luna', 'The Moon', 'rws', '["La Luna","The Moon","Moon","Luna","XVIII","18","inconsciente","sueño","incertidumbre","misterio"]', 'Navegación del territorio incierto, memoria inconsciente, intuición y sombras proyectadas.', 'Confusión disipada, salida paulatina de la niebla o exceso de susceptibilidad emotiva.', '["inconsciente","sueño","incertidumbre","misterio"]', 'Los dos perros aullando bajo la luz pálida mientras el cangrejo emerge del fondo.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-19', '19-el-sol', 'major', NULL, 19, 'XIX', 'El Sol', 'The Sun', 'rws', '["El Sol","The Sun","Sun","Sol","XIX","19","claridad","calidez","franqueza","presencia"]', 'Claridad meridiana, vitalidad compartida, franqueza y comprensión directa.', 'Exposición agotadora, optimismo forzado o vitalidad momentáneamente velada.', '["claridad","calidez","franqueza","presencia"]', 'Luz directa sin artificios en un jardín abierto.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-20', '20-el-juicio', 'major', NULL, 20, 'XX', 'El Juicio', 'Judgement', 'rws', '["El Juicio","Judgement","Judgment","Juicio","XX","20","llamado","despertar","balance","vocación"]', 'Llamado inaplazable, recapitulación honesta de la historia vivida, despertar.', 'Autojuicio paralizante, desoír una vocación clara o postergar una respuesta.', '["llamado","despertar","balance","vocación"]', 'Responder con nombre propio cuando una etapa convoca a integrarse.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('major-21', '21-el-mundo', 'major', NULL, 21, 'XXI', 'El Mundo', 'The World', 'rws', '["El Mundo","The World","World","Mundo","XXI","21","culminación","totalidad","síntesis","presencia"]', 'Culminación íntegra de un ciclo, habitar el propio lugar, síntesis viva.', 'Cierre incompleto, demora en el último gesto o dificultad para soltar la obra.', '["culminación","totalidad","síntesis","presencia"]', 'La guirnalda cerrada que abraza los cuatro puntos cardinales.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-00', 'thoth-00-the-fool', 'major', NULL, 0, '0', 'El Loco (The Fool)', 'The Fool', 'thoth', '["El Loco (The Fool)","The Fool","0","Thoth","Crowley","aire puro","éter","origen","inocencia"]', 'Silencio primordial, éter puro, la inocencia divina antes del pensamiento.', 'Locura impulsiva, disolución descontrolada o desconexión del cuerpo.', '["aire puro","éter","origen","inocencia"]', 'Dionisio con cuernos de oro y tigre mordisqueando sus ropas. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');
