INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-swords-14', 'thoth-espadas-knight', 'minor', 'swords', 14, 'KN', 'Caballero de Espadas (Thoth)', 'Knight of Swords', 'thoth', '["Caballero de Espadas (Thoth)","Caballero de Espadas","Knight of Swords","Fuego de Aire","Thoth","Crowley"]', 'Fuerza subelemental pura: Fuego de Aire encarnada con dinamismo en la corte de Espadas.', 'Desbalance o reactividad en la manifestación de Fuego de Aire.', '["espadas","fuego de aire","figura thoth"]', 'Fuego de Aire en el sistema ceremonial de Thoth.');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-15', 'thoth-15-the-devil', 'major', NULL, 15, 'XV', 'El Diablo (The Devil)', 'The Devil', 'thoth', '["El Diablo (The Devil)","The Devil","XV","15","Thoth","Crowley","pan","capricornio","impulso creador","ojo de shiva"]', 'Pan salvaje, energía telúrica y risa sagrada de la naturaleza no domesticada.', 'Perversión egoísta, miedo a la sexualidad o fascinación con la propia sombra.', '["pan","capricornio","impulso creador","ojo de shiva"]', 'La cabra de Mendes con el tercer ojo sobre el caduceo erecto y los árboles solares. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-16', 'thoth-16-the-tower', 'major', NULL, 16, 'XVI', 'La Torre (The Tower)', 'The Tower', 'thoth', '["La Torre (The Tower)","The Tower","XVI","16","Thoth","Crowley","ojo de horus","marte","guerra sagrada","relámpago"]', 'El Ojo de Horus desatando el relámpago que purifica la fortaleza del ego cerrado.', 'Catástrofe destructiva sin aprendizaje o aferramiento a escombros.', '["ojo de horus","marte","guerra sagrada","relámpago"]', 'La torre rota entre fauces ardientes y el ojo abriéndose en lo alto. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-17', 'thoth-17-the-star', 'major', NULL, 17, 'XVII', 'La Estrella (The Star)', 'The Star', 'thoth', '["La Estrella (The Star)","The Star","XVII","17","Thoth","Crowley","nuit","acuario","gracia","estrellas"]', 'Nuit vertiendo su néctar celeste en las copas de oro y plata, gracia infinita.', 'Esperanza vacía, distanciamiento frío o soberbia intelectual.', '["nuit","acuario","gracia","estrellas"]', 'La doncella celeste curvándose sobre el cielo nocturno vertiendo licor estelar. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-18', 'thoth-18-the-moon', 'major', NULL, 18, 'XVIII', 'La Luna (The Moon)', 'The Moon', 'thoth', '["La Luna (The Moon)","The Moon","XVIII","18","Thoth","Crowley","piscis","khepri","inframundo","ilusión sombría"]', 'El umbral de Khepri a través del inframundo oscuro, prueba nocturna antes del amanecer.', 'Engaño psicótico, terror irracional a la oscuridad o alucinación.', '["piscis","khepri","inframundo","ilusión sombría"]', 'Los centinelas de Anubis custodiando las torres mientras el escarabajo empuja el sol. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-19', 'thoth-19-the-sun', 'major', NULL, 19, 'XIX', 'El Sol (The Sun)', 'The Sun', 'thoth', '["El Sol (The Sun)","The Sun","XIX","19","Thoth","Crowley","heru-ra-ha","sol","alegría sagrada","inocencia radiante"]', 'Heru-ra-ha resplandeciente, alegría infantil sagrada, coronación solar de la vida.', 'Arrogancia solar, soberbia narcisista o quemazón vital.', '["heru-ra-ha","sol","alegría sagrada","inocencia radiante"]', 'Dos niños alados danzando desnudos sobre la colina verde bajo el sol radiante. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-20', 'thoth-20-the-aeon', 'major', NULL, 20, 'XX', 'El Eón (The Aeon)', 'The Aeon', 'thoth', '["El Eón (The Aeon)","The Aeon","XX","20","Thoth","Crowley","eón de horus","juicio thoth","nuevo ciclo","nuit y hadit"]', 'Apertura del nuevo Eón de Horus, transformación radical de la conciencia histórica.', 'Nostalgia por órdenes pasados, apego al Eón de Osiris o miedo a la libertad.', '["eón de horus","juicio thoth","nuevo ciclo","nuit y hadit"]', 'Nuit en el cielo, Hadit como esfera alada y Horus coronado en el centro. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');
INSERT OR IGNORE INTO cards_catalog (id, slug, arcana, suit, rank_number, roman_numeral, canonical_name, name_en, deck_tradition, search_keywords_json, traditional_upright, traditional_reversed, traditional_keywords_json, archetype_note) VALUES ('thoth-major-21', 'thoth-21-the-universe', 'major', NULL, 21, 'XXI', 'El Universo (The Universe)', 'The Universe', 'thoth', '["El Universo (The Universe)","The Universe","XXI","21","Thoth","Crowley","gran obra","saturno","consumación","danza cósmica"]', 'Consumación final de la Gran Obra, danza cósmica con la serpiente del espacio-tiempo.', 'Inercia final, pesadez material que impide coronar la obra.', '["gran obra","saturno","consumación","danza cósmica"]', 'La doncella en éxtasis danzando con la serpiente envuelta en la elipse celeste. (Tarot de Thoth - Aleister Crowley & Frieda Harris).');

