-- ----------------------------------------------------------------------------
INSERT OR IGNORE INTO spread_templates (id, user_id, name, category, description, positions_json, is_builtin, created_at) VALUES ('spread-celtic-cross', NULL, 'Cruz Celta (10 cartas)', 'Clásica de 10 cartas', 'Estructura tradicional completa de diez cartas que combina la cruz de la situación actual con la columna de evolución.', '[{"positionIndex":1,"title":"Situación central","prompt":"Tema principal que vive hoy el consultante.","coordX":30,"coordY":50},{"positionIndex":2,"title":"Lo que cruza","prompt":"Factor que se interpone, desafía o impulsa el tema central.","coordX":38,"coordY":54},{"positionIndex":3,"title":"Base / Raíz","prompt":"Causa de fondo o experiencia pasada que sostiene el asunto.","coordX":30,"coordY":82},{"positionIndex":4,"title":"Pasado reciente","prompt":"Etapa o acontecimiento que está quedando atrás.","coordX":12,"coordY":50},{"positionIndex":5,"title":"Meta consciente","prompt":"Lo que el consultante espera, piensa o busca lograr.","coordX":30,"coordY":18},{"positionIndex":6,"title":"Futuro próximo","prompt":"Lo que se acerca en el corto plazo.","coordX":52,"coordY":50},{"positionIndex":7,"title":"Actitud propia","prompt":"Cómo se para y se siente el consultante ante la situación.","coordX":82,"coordY":84},{"positionIndex":8,"title":"Entorno externo","prompt":"Influencia familiar, laboral o de las personas involucradas.","coordX":82,"coordY":62},{"positionIndex":9,"title":"Deseos y miedos","prompt":"Expectativas internas o dudas frente al cambio.","coordX":82,"coordY":40},{"positionIndex":10,"title":"Resultado final","prompt":"Síntesis general y cierre hacia donde tiende el proceso.","coordX":82,"coordY":18}]', 1, '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO spread_templates (id, user_id, name, category, description, positions_json, is_builtin, created_at) VALUES ('spread-simple-cross', NULL, 'Cruz de cinco cartas', 'Clásica de 5 cartas', 'Estructura en cruz con síntesis central para contrastar lo que ayuda, lo que frena, la meta buscada y la base del tema.', '[{"positionIndex":1,"title":"A favor","prompt":"Recurso disponible, apoyo o punto fuerte que acompaña.","coordX":22,"coordY":50},{"positionIndex":2,"title":"En contra / Obstáculo","prompt":"Dificultad principal, bloqueo o aspecto que genera resistencia.","coordX":78,"coordY":50},{"positionIndex":3,"title":"Meta / Lo que se busca","prompt":"Objetivo consciente, expectativa o lo que se desea lograr.","coordX":50,"coordY":18},{"positionIndex":4,"title":"Base / Origen","prompt":"Raíz del asunto, motivación de fondo o condición previa.","coordX":50,"coordY":82},{"positionIndex":5,"title":"Centro / Síntesis","prompt":"Resumen central y consejo integrador de las cuatro posiciones.","coordX":50,"coordY":50}]', 1, '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO spread_templates (id, user_id, name, category, description, positions_json, is_builtin, created_at) VALUES ('spread-horseshoe-7', NULL, 'Herradura de siete cartas', 'Clásica de 7 cartas', 'Recorrido en arco de siete posiciones para analizar la evolución de un problema, factores externos, consejos y desenlace.', '[{"positionIndex":1,"title":"Pasado","prompt":"Situación previa que influye directamente en la consulta.","coordX":14,"coordY":75},{"positionIndex":2,"title":"Presente","prompt":"Punto exacto en el que se encuentra hoy el consultante.","coordX":24,"coordY":45},{"positionIndex":3,"title":"Influencias ocultas","prompt":"Factores que aún no se ven con claridad o se pasan por alto.","coordX":36,"coordY":22},{"positionIndex":4,"title":"Obstáculo principal","prompt":"Desafío concreto que es necesario atravesar o resolver.","coordX":50,"coordY":15},{"positionIndex":5,"title":"Entorno y otras personas","prompt":"Actitud del entorno, vínculos o circunstancias externas.","coordX":64,"coordY":22},{"positionIndex":6,"title":"Acción recomendada","prompt":"Mejor postura o decisión práctica a tomar frente al tema.","coordX":76,"coordY":45},{"positionIndex":7,"title":"Resultado / Desenlace","prompt":"Resolución probable integrando las posiciones anteriores.","coordX":86,"coordY":75}]', 1, '2026-01-01T00:00:00.000Z');
INSERT OR IGNORE INTO spread_templates (id, user_id, name, category, description, positions_json, is_builtin, created_at) VALUES ('spread-triad-observation', NULL, 'Pasado, Presente y Futuro (3 cartas)', 'Clásica de 3 cartas', 'Estructura lineal de tres posiciones para ver el origen del tema, la situación actual y hacia dónde se dirige.', '[{"positionIndex":1,"title":"Pasado / Origen","prompt":"Antecedentes recientes o causa que trajo la situación hasta hoy.","coordX":20,"coordY":50},{"positionIndex":2,"title":"Presente / Estado actual","prompt":"Lo que está ocurriendo ahora mismo y pide atención directa.","coordX":50,"coordY":50},{"positionIndex":3,"title":"Futuro / Tendencia","prompt":"Dirección probable o próximo paso si se mantiene el rumbo actual.","coordX":80,"coordY":50}]', 1, '2026-01-01T00:00:00.000Z');
